(function() {
  try {
    const fields = {
      'field-name': 'Jane Smith',
      'field-address': '123 Test Lane',
      'field-city': 'Anytown',
      'field-zip': '00000',
      'field-card': '4111111111111111',
      'field-expiry': '12/28',
      'field-cvv': '123'
    };

    for (const [id, val] of Object.entries(fields)) {
      const host = document.getElementById(id);
      if (host && host.shadowRoot) {
        const input = host.shadowRoot.querySelector('input');
        if (input) {
          input.value = val;
          input.dispatchEvent(new Event('input', {bubbles: true}));
          input.dispatchEvent(new Event('change', {bubbles: true}));
        }
      }
    }

    const placeOrderBtn = document.getElementById('place-order-btn');
    if (placeOrderBtn) {
      placeOrderBtn.click();
    }
    return 'Filled and submitted successfully';
  } catch (e) {
    return 'Error: ' + e.message;
  }
})()

(function(){
  try {
    const form = document.querySelector('#checkout-form');
    if (!form) return 'Form not found';

    const setField = (childId, value) => {
      const el = form.querySelector(childId);
      if (el) {
        let targetInput = el;
        if (el.shadowRoot) {
          targetInput = el.shadowRoot.querySelector('input') || el;
        }
        targetInput.value = value;
        targetInput.dispatchEvent(new Event('input', { bubbles: true }));
        targetInput.dispatchEvent(new Event('change', { bubbles: true }));
      }
    };

    setField('#field-name', 'Jane Smith');
    setField('#field-address', '123 Test Lane');
    setField('#field-city', 'Anytown');
    setField('#field-zip', '00000');
    setField('#field-card', '4111111111111111');
    setField('#field-expiry', '12/28');
    setField('#field-cvv', '123');

    const btn = document.querySelector('#place-order-btn');
    if (btn) {
      btn.click();
      return 'Filled fields and clicked place order successfully';
    }
    return 'Place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
